# -------------------------
# Session state
# -------------------------
DEFAULTS = {
    "chunks": [],
    "retriever": None,
    "question": None,
    "question_context": [],
    "oral_eval": None,
    "oral_eval_context": [],
    "practice": None,
    "practice_context": [],
    "practice_eval": None,
    "weak_queue": [],
    "ai_call_count": 0,
    "attempts": [],
    "source_files": {},
    "cloud_client": None,
    "cloud_user_id": "",
    "cloud_username": "",
    "cloud_loaded": False,
    "projects": [],
    "current_project_id": "",
    "current_project_name": "",
    "loaded_material_project_id": "",
    "current_project_files": [],
}
for key, value in DEFAULTS.items():
    if key not in st.session_state:
        st.session_state[key] = value


def _secret(name: str, default=""):
    try:
        return st.secrets.get(name, default)
    except Exception:
        return default



def cloud_config():
    return {
        "url": str(_secret("SUPABASE_URL", "")).strip(),
        "key": str(_secret("SUPABASE_KEY", "")).strip(),
    }


def cloud_enabled() -> bool:
    cfg = cloud_config()
    return bool(cfg["url"] and cfg["key"])


def cloud_logged_in() -> bool:
    return bool(
        st.session_state.get("cloud_client")
        and st.session_state.get("cloud_user_id")
    )


def rebuild_weak_queue(attempts: list[dict]) -> list[str]:
    """Prioritize recent weaknesses inside the currently selected project."""
    seen = set()
    ordered = []
    for attempt in reversed(attempts):
        for concept in attempt.get("weak_concepts") or []:
            concept = str(concept).strip()
            if concept and concept not in seen:
                seen.add(concept)
                ordered.append(concept)
    return ordered[:20]


def current_project_attempts() -> list[dict]:
    project_id = st.session_state.get("current_project_id", "")
    if not project_id:
        return []
    return [
        a for a in st.session_state.get("attempts", [])
        if str(a.get("project_id") or "") == str(project_id)
    ]


class MemoryUpload:
    """Minimal UploadedFile-compatible wrapper for files downloaded from project storage."""
    def __init__(self, name: str, raw: bytes):
        self.name = name
        self._raw = raw

    def getvalue(self):
        return self._raw


def reset_learning_screen_state(clear_materials: bool = True):
    st.session_state.question = None
    st.session_state.question_context = []
    st.session_state.oral_eval = None
    st.session_state.oral_eval_context = []
    st.session_state.practice = None
    st.session_state.practice_context = []
    st.session_state.practice_eval = None
    if clear_materials:
        st.session_state.chunks = []
        st.session_state.retriever = None
        st.session_state.source_files = {}
        st.session_state.current_project_files = []


def set_current_project(project_id: str):
    project = next((p for p in st.session_state.get("projects", []) if p["id"] == project_id), None)
    st.session_state.current_project_id = project_id or ""
    st.session_state.current_project_name = project["name"] if project else ""
    st.session_state.weak_queue = rebuild_weak_queue(current_project_attempts())
    if st.session_state.get("loaded_material_project_id") != project_id:
        reset_learning_screen_state(clear_materials=True)
        st.session_state.loaded_material_project_id = ""


def load_current_project_materials(force: bool = False):
    if not cloud_logged_in() or not st.session_state.get("current_project_id"):
        return
    project_id = st.session_state.current_project_id
    if not force and st.session_state.get("loaded_material_project_id") == project_id:
        return

    files = load_project_files(
        st.session_state.cloud_client,
        st.session_state.cloud_user_id,
        project_id,
    )
    page_records = []
    source_files = {}
    failed = []
    for meta in files:
        try:
            raw = download_project_file(st.session_state.cloud_client, meta["storage_path"])
            wrapped = MemoryUpload(meta["file_name"], raw)
            page_records.extend(extract_uploaded_file(wrapped, meta["kind"]))
            source_files[meta["file_name"]] = {
                "raw": raw,
                "suffix": meta["suffix"],
                "kind": meta["kind"],
            }
        except Exception as e:
            failed.append(f"{meta['file_name']}: {e}")

    chunks = chunk_records(page_records)
    st.session_state.current_project_files = files
    st.session_state.chunks = chunks
    st.session_state.retriever = LocalRetriever(chunks) if chunks else None
    st.session_state.source_files = source_files
    st.session_state.loaded_material_project_id = project_id
    reset_learning_screen_state(clear_materials=False)
    st.session_state.weak_queue = rebuild_weak_queue(current_project_attempts())
    if failed:
        st.warning("일부 프로젝트 파일을 불러오지 못했습니다: " + " / ".join(failed[:3]))


def record_attempt(attempt: dict):
    """Save the learning result under the selected project."""
    local_attempt = dict(attempt)
    project_id = st.session_state.get("current_project_id", "")
    local_attempt["project_id"] = project_id

    if cloud_logged_in():
        if not project_id:
            st.warning("프로젝트가 선택되지 않아 학습 기록을 영구 저장하지 못했습니다.")
        else:
            try:
                saved = save_attempt(
                    st.session_state.cloud_client,
                    st.session_state.cloud_user_id,
                    project_id,
                    local_attempt,
                )
                st.session_state.attempts.append(saved)
                return
            except Exception as e:
                st.warning(
                    "학습 기록을 클라우드에 저장하지 못했습니다. "
                    f"현재 세션에는 남아 있습니다. ({e})"
                )

    st.session_state.attempts.append(local_attempt)


def load_cloud_history():
    if not cloud_logged_in():
        return
    st.session_state.projects = load_projects(
        st.session_state.cloud_client,
        st.session_state.cloud_user_id,
    )
    st.session_state.attempts = load_attempts(
        st.session_state.cloud_client,
        st.session_state.cloud_user_id,
    )
    valid_ids = {p["id"] for p in st.session_state.projects}
    current = st.session_state.get("current_project_id", "")
    if current not in valid_ids:
        current = st.session_state.projects[0]["id"] if st.session_state.projects else ""
    set_current_project(current)
    st.session_state.cloud_loaded = True


def clear_cloud_session():
    st.session_state.cloud_client = None
    st.session_state.cloud_user_id = ""
    st.session_state.cloud_username = ""
    st.session_state.cloud_loaded = False
    st.session_state.attempts = []
    st.session_state.weak_queue = []
    st.session_state.projects = []
    st.session_state.current_project_id = ""
    st.session_state.current_project_name = ""
    st.session_state.loaded_material_project_id = ""
    reset_learning_screen_state(clear_materials=True)

def get_provider_config():
    provider = st.session_state.get("provider", "고려대 API Gateway")

    if provider == "고려대 API Gateway":
        return {
            "provider": provider,
            "api_key": st.session_state.get("user_api_key", "").strip(),
            "base_url": "https://factchat.mindlogic-kr-api.com/v1/gateway",
            "model": st.session_state.get("user_model", "gpt-5.6-luna").strip(),
        }

    return {
        "provider": "OpenAI API",
        "api_key": st.session_state.get("user_api_key", "").strip(),
        "base_url": None,
        "model": st.session_state.get("user_model", "gpt-5.6-luna").strip(),
    }


def get_engine():
    cfg = get_provider_config()

    if not cfg["api_key"]:
        st.error("왼쪽 사이드바에 본인의 API Key를 입력해 주세요.")
        return None

    max_calls = 30
    used = int(st.session_state.get("ai_call_count", 0))
    if used >= max_calls:
        st.error(
            "현재 브라우저 세션에서 AI를 30회 호출했습니다. "
            "새 학습 세션을 시작하려면 페이지를 다시 열어 주세요."
        )
        return None

    return AIEngine(
        cfg["api_key"],
        model=cfg["model"],
        base_url=cfg["base_url"],
    )


def pick_context(query: str, k: int = 7):
    retriever = st.session_state.retriever
    if retriever is None:
        return []
    if query.strip():
        return retriever.search(query, k=k)
    return retriever.representative(k=k)


def safe_api_call(fn, *args, **kwargs):
    try:
        result = fn(*args, **kwargs)
        st.session_state.ai_call_count = int(st.session_state.get("ai_call_count", 0)) + 1
        return result
    except Exception as e:
        message = str(e)
        st.error(f"AI 호출 중 오류가 발생했습니다: {message}")
        if "credit_balance_exhausted" in message or "insufficient_quota" in message:
            st.warning("OpenAI API 크레딧이 없습니다. 앱 배포와 화면 사용은 가능하지만 AI 생성 기능은 크레딧 충전 후 작동합니다.")
        elif any(token in message.lower() for token in ["image", "vision", "multimodal", "input_image"]):
            st.warning(
                "현재 선택한 모델 또는 API Gateway가 이미지 입력을 지원하지 않을 수 있습니다. "
                "이미지 입력이 가능한 모델인지 확인하거나 풀이를 텍스트로 입력해 주세요."
            )
        else:
            st.info("API Key, 모델 이름, API Gateway 상태를 확인해 주세요.")
        return None


def verdict_badge(verdict: str):
    mapping = {
        "correct": ("✅", "정답/충분"),
        "partial": ("🟡", "부분 정답"),
        "incorrect": ("❌", "오답"),
    }
    return mapping.get(verdict, ("ℹ️", verdict))


def parse_number(text: str):
    if not text:
        return None
    s = text.replace(",", "")
    matches = re.findall(r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?", s)
    if not matches:
        return None
    # 최종 답 입력칸이므로 마지막 숫자를 채점값으로 사용
    try:
        return float(matches[-1])
    except ValueError:
        return None



def show_evidence(items: list[dict], evidence_ids=None, title: str = "근거 자료", max_items: int = 3):
    """Show exact source/page, extracted source text, and PDF page preview when available."""
    selected = select_evidence(items, evidence_ids, fallback=max_items)[:max_items]
    if not selected:
        return

    with st.expander(title):
        if evidence_ids:
            st.caption("AI가 [자료 N] 중 직접 근거로 지정한 부분입니다. 원문은 앱이 업로드 자료에서 직접 추출한 내용입니다.")
        else:
            st.caption("AI에 전달된 관련 자료 중 상위 근거입니다. 원문은 앱이 업로드 자료에서 직접 추출한 내용입니다.")

        for i, item in enumerate(selected, start=1):
            kind_label = "강의자료" if item.get("kind") == "lecture" else "기출문제"
            score = item.get("score")
            score_text = f" · 검색 관련도 {score:.2f}" if isinstance(score, (int, float)) else ""

            with st.container(border=True):
                st.markdown(f"**{i}. {source_location(item)}**")
                st.caption(f"{kind_label}{score_text}")
                st.markdown("**원문 발췌**")
                excerpt = (item.get("text") or "").strip()
                st.write(excerpt[:1200] + ("…" if len(excerpt) > 1200 else ""))

                source_file = st.session_state.get("source_files", {}).get(item.get("source"))
                if source_file and source_file.get("suffix") == "pdf":
                    digest = hashlib.md5(
                        f"{title}|{item.get('source')}|{item.get('page')}|{i}".encode("utf-8")
                    ).hexdigest()[:12]
                    if st.checkbox("실제 PDF 페이지 보기", key=f"pdf_evidence_{digest}"):
                        try:
                            png = render_pdf_page_png(source_file["raw"], int(item["page"]))
                            st.image(
                                png,
                                caption=f"{item['source']} · p.{item['page']}",
                                use_container_width=True,
                            )
                        except Exception as e:
                            st.info(f"페이지 미리보기를 표시하지 못했습니다: {e}")


